int do_iccprofile_item(pcap_t *p, struct ic_profile *profile, uint8_t *data, uint16_t length) { if (length > 3) { uint16_t sel = dbuf_getu32be(p->out, data); uint16_t len = length - 4; de_dbg(p, "ICC profile segment, selector=%d, data len=%d", (int)sel, (int)len); if (sel != 1) { dbuf_close(profile->out); profile->out = NULL; } if (sel == 0) profile->out = dbuf_create_output_file(p, "icc", NULL, 1); } if (sel == 0 || sel == 1) return ; dbuf_copy(p->out, &data->icc, len, profile->out); }